__global__ void __launch_bounds__(kThreads, 1) tc_h_kernel(const float* __restrict__ W, const __grid_constant__ CUtensorMap mapE1,
    const __grid_constant__ CUtensorMap mapE2, const float* __restrict__ bias, OutPtrs outs, const float* __restrict__ emb, uint4* emb16, unsigned* sync, TileCfg p) {
