'''
open('/tmp/r10/tch.cu', 'w').write(TCH)
r = subprocess.run('nvcc -O3 --use_fast_math -std=c++17 -gencode arch=compute_100a,code=sm_100a -shared -Xcompiler -fPIC /tmp/r10/tch.cu -o /tmp/r10/tch.so -lcuda -Xptxas -v 2>&1 | grep -E "error|registers|stack" | head', shell=True, capture_output=True, text=True)
