names = {0:'entry',1:'prolog',10:'embcvt',2:'embwait',9:'cvt1st',3:'full0',4:'fullL0',11:'tfree',5:'full1',6:'fullL1',12:'acc0',14:'epi0',13:'acc1',15:'epi1',8:'end'}
