        __syncwarp(); }
      if (elect_one()) umma_commit2(smem_u32(&accum));
      __syncwarp(); }
  } else if (warp >= kCvtWarp0) {
    const int cw = warp - kCvtWarp0, g = cw / kGroupWarps, w = cw % kGroupWarps;
    const int half = lane >> 4, c4 = lane & 15, jj = c4 >> 1;
    const int rb = w * 16 + half;
    const float* src = W + (size_t)(m0_of(0) + rb) * kD + c4 * 4;
    uint32_t sOff[8];
#pragma unroll
    for (int i = 0; i < 8; ++i) { const int r = rb + 2 * i; sOff[i] = r * 128 + ((jj ^ (r & 7)) << 4) + (c4 & 1) * 8; }
    uint64_t pol; asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    const uint32_t fullL = mapa0(smem_u32(&full[0]));
    float4 buf[8];
    load_kb(buf, src, g, pol);
    for (int j = 0; j < p.nb; ++j) {
      for (int kb = g; kb < kKB; kb += kGroups) { const int t = j * kKB + kb, s = t % p.stages;
        if (t >= p.stages) mbar_wait(smem_u32(&empty[s]), ((t / p.stages) - 1) & 1);
        else if (p.fuse) mbar_wait(smem_u32(&sfree), 0);
        const uint32_t a = sbase + s * stageBytes;
#pragma unroll
        for (int i = 0; i < 8; ++i) { const float4 x = buf[i]; sts64(a + sOff[i], pack_h2(x.x, x.y), pack_h2(x.z, x.w)); }
        asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
        asm volatile("bar.sync %0, %1;" ::"r"(1 + g), "r"(32 * kGroupWarps) : "memory");
        if (w == 0) { if (elect_one()) arrive_cluster(fullL + 8 * s); __syncwarp(); }
        if (kb + kGroups < kKB) load_kb(buf, src, kb + kGroups, pol); }
      if (j + 1 < p.nb) { src = W + (size_t)(m0_of(j + 1) + rb) * kD + c4 * 4; load_kb(buf, src, g, pol);
        epilogue(j, cw >> 2, kCvtWarps / 4);
        asm volatile("tcgen05.fence::before_thread_sync;");
        asm volatile("bar.sync %0, %1;" ::"r"(1 + kGroups), "r"(32 * kCvtWarps) : "memory");
        if (cw == 0) { if (elect_one()) arrive_cluster(mapa0(smem_u32(&tfree))); __syncwarp(); } }
    }
  }
  if (p.nb == 1) epilogue(0, warp >> 2, kThreads / 128);
  else if (warp >= kCvtWarp0) epilogue(p.nb - 1, (warp - kCvtWarp0) >> 2, kCvtWarps / 4);
  asm volatile("tcgen05.fence::before_thread_sync;");
  cluster_sync();
  if (warp == 3) { asm volatile("tcgen05.fence::after_thread_sync;");
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(p.tmem_cols)); }
#endif
}
}  // namespace
extern "C" int run_h(const float* emb, const float* W, const float* bias, float* o0, float* o1, float* o2, float* o3, float* o4, float* o5,
                     void* emb16, int B, cudaStream_t stream, int maxst) {
  TileCfg p; p.B = B; p.nb = B <= 512 ? 1 : 2; p.ntile = ((B + p.nb - 1) / p.nb + 15) / 16 * 16;
  p.n1 = p.ntile < 256 ? p.ntile : 256; p.n2 = p.ntile - p.n1;
  p.tmem_cols = p.n2 ? 512 : p.n1 <= 32 ? 32 : p.n1 <= 64 ? 64 : p.n1 <= 128 ? 128 : 256;
  p.n8 = B * kD / 8;
  const int stageBytes = kABlk + p.ntile / 2 * 128;
  p.stages = (kSmemDyn - 1024) / stageBytes; if (p.stages > maxst) p.stages = maxst;
  const int grid = 2 * kPairs;
  CUtensorMap mE1, mE2; cuuint32_t es[2] = {1, 1};
  cuuint64_t dE[2] = {(cuuint64_t)kD, (cuuint64_t)B}, sE[1] = {(cuuint64_t)kD * 2};
  cuuint32_t bE1[2] = {kBK, (cuuint32_t)(p.n1 / 2)}, bE2[2] = {kBK, (cuuint32_t)(p.n2 ? p.n2 / 2 : 8)};
  cuTensorMapEncodeTiled(&mE1, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE1, es, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
  cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
  cudaLaunchAttribute at[1]; at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = 2; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  static unsigned* sync = nullptr;
  if (!sync) { cudaFuncSetAttribute(tc_h_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn); cudaMalloc(&sync, 8); cudaMemset(sync, 0, 8); cudaDeviceSynchronize(); }
  p.fuse = 1;
  OutPtrs op; op.p[0]=o0; op.p[1]=o1; op.p[2]=o2; op.p[3]=o3; op.p[4]=o4; op.p[5]=o5;
  cudaLaunchConfig_t cfg = {}; cfg.gridDim = dim3(grid); cfg.blockDim = dim3(kThreads); cfg.dynamicSmemBytes = p.stages * stageBytes + 1024;
  cfg.stream = stream; cfg.attrs = at; cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, tc_h_kernel, W, mE1, mE2, bias, op, emb, (uint4*)emb16, sync, p);
  return (int)cudaGetLastError();
