```cuda file=tc_h.cu
#include <cuda_runtime.h>
#include <cuda.h>
#include <cstdint>

// B > 256 (dispatched from kernel.cu; correct for any 1 <= B <= 1024): warp-specialised 2SM tcgen05 kind::f16 GEMM.
// fp16 operands (cvt.rn, round to nearest), fp32 accumulation in TMEM over the full K = 3072; on these inputs fp16
// rounds like tf32 (11 significant bits) and kind::f16 runs at twice the kind::tf32 rate.
// Tiling as in r6/r7: a cluster of two CTAs computes a 256-row W tile (cta_group::2, M = 256) against batch tiles of
// ntile = Bpad (B <= 512) or roundup(B / 2, 16) (B > 512); ntile > 256 uses two accumulators (N1 = 256 at TMEM column
// 0, N2 at column 256). One k-block = 64 fp16 = one 128 B swizzle row, 4 UMMAs of K = 16 per accumulator.
// r8: one launch of 72 persistent pairs. A pair runs its nb work items back to back (item j = pair + 72 j: W tile
// item / nb, batch tile item % nb, so sibling batch tiles of one W tile still run on adjacent pairs at the same time
// and share W through L2). The W ring continues across items: the converters issue the next item's first loads,
// then drain the finished accumulator (epilogue), then signal tfree so the MMA warp may overwrite TMEM.
// r8: emb is converted to fp16 inside the kernel. At CTA start one bulk copy brings this CTA's 1/144 slice of emb
// (fp32) into the still-empty stage area; warps 0-3 convert it to the fp16 scratch, then add 1 to a grid-wide
// counter (red.release.gpu). The emb TMA producer waits until all CTAs have converted (acquire, then
// fence.proxy.async.global), which is hidden behind the first W k-blocks; the converters wait for the staging to be
// consumed before their first STS. The last CTA to pass the wait resets the counter, so it is zero for every call.
// This needs all 144 CTAs co-resident (checked once with cudaOccupancyMaxActiveClusters); otherwise the fp16
// conversion runs as a separate pre-pass kernel (r7 path).
// Converters (r7): G = 3 rotating groups of 8 warps; group g owns k-blocks g, g + G, ... of every item. For each it
// loads the whole 32 KB slice, converts, stores, fences, bar.syncs its 256 threads and one lane does the
// release.cluster arrive on the leader's full barrier, and only then issues the next loads (a release arrive waits for
// the thread's own loads in flight). stages >= G is required (parity aliasing).
// r10: the ring has 4 stages for the nb = 2 tile of ntile >= 464 (B = 919: 90.4-90.8 vs 91.6-93.1 us, two
// containers) and 3 stages everywhere else (a 4th stage is 1.0-3.6 us slower at 384-853).
// Roles (warp-uniform, elect.sync issue): warp 0 emb TMA producer, warp 1 (leader) MMA issuer, warp 3 TMEM alloc,
// warps 0-3 emb conversion, warps 4-27 W converters. Epilogue: all 28 warps when nb = 1, the 24 converter warps
// otherwise (TMEM lane quadrant warp % 4, 16-column groups interleaved).
namespace {
constexpr int kD = 3072, kN = 6 * kD, kRows = 128, kBK = 64, kKB = kD / kBK, kABlk = kRows * kBK * 2;
constexpr int kMaxStages = 4, kSmemDyn = 225 * 1024;
constexpr int kCvtWarp0 = 4, kGroupWarps = 8, kGroups = 3, kCvtWarps = kGroupWarps * kGroups;
constexpr int kThreads = (kCvtWarp0 + kCvtWarps) * 32;
constexpr int kPairs = kN / (2 * kRows);   // 72 W tiles of 256 rows = persistent pairs
static_assert(kGroupWarps * 16 == kRows, "each converter warp converts 16 W rows per k-block");
static_assert(kMaxStages >= kGroups, "a rotating group must not run two barrier phases ahead");
static_assert(kKB % kGroups == 0, "group g owns the same k-blocks in every item");
static_assert(kCvtWarps % 4 == 0, "the converter epilogue covers whole TMEM lane quadrants");
struct OutPtrs { float* p[6]; };
struct TileCfg { int B, ntile, n1, n2, stages, nb, tmem_cols, fuse, n8; };

#if defined(__CUDA_ARCH_FEAT_SM100_ALL)
__device__ __forceinline__ uint32_t smem_u32(const void* p) { return (uint32_t)__cvta_generic_to_shared(p); }
__device__ __forceinline__ uint32_t mapa0(uint32_t a) {
  uint32_t r;
  asm volatile("mapa.shared::cluster.u32 %0, %1, %2;" : "=r"(r) : "r"(a), "r"(0));
  return r;
}
__device__ __forceinline__ bool try_wait(uint32_t bar, uint32_t par) {
  uint32_t ok;
  asm volatile("{ .reg .pred p; mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2; selp.u32 %0, 1, 0, p; }"
               : "=r"(ok) : "r"(bar), "r"(par) : "memory");
  return ok != 0;
}
__device__ __forceinline__ bool try_wait_cluster(uint32_t bar, uint32_t par) {
  uint32_t ok;
  asm volatile("{ .reg .pred p; mbarrier.try_wait.parity.acquire.cluster.shared::cta.b64 p, [%1], %2; selp.u32 %0, 1, 0, p; }"
               : "=r"(ok) : "r"(bar), "r"(par) : "memory");
  return ok != 0;
}
__device__ __forceinline__ void mbar_wait(uint32_t bar, uint32_t par) {
  uint32_t n = 0;
  while (!try_wait(bar, par))
    if (++n > (1u << 27)) __trap();   // a broken pipeline fails the call instead of hanging it
}
__device__ __forceinline__ void mbar_wait_cluster(uint32_t bar, uint32_t par) {
  uint32_t n = 0;
  while (!try_wait_cluster(bar, par))
    if (++n > (1u << 27)) __trap();
}
__device__ __forceinline__ void mbar_init(uint32_t bar, uint32_t count) {
  asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(bar), "r"(count));
}
__device__ __forceinline__ uint32_t elect_one() {
  uint32_t pred = 0;
  asm volatile("{\n .reg .b32 rx;\n .reg .pred px;\n elect.sync rx|px, %1;\n selp.b32 %0, 1, 0, px;\n}"
               : "=r"(pred) : "r"(0xffffffffu));
  return pred;
}
__device__ __forceinline__ void umma_commit2(uint32_t bar) {
  asm volatile("tcgen05.commit.cta_group::2.mbarrier::arrive::one.shared::cluster.multicast::cluster.b64 [%0], %1;"
               ::"r"(bar), "h"((uint16_t)3) : "memory");
}
__device__ __forceinline__ void umma2(uint32_t t, uint64_t a, uint64_t b, uint32_t idesc, uint32_t acc) {
  asm volatile("{ .reg .pred p; setp.ne.b32 p, %4, 0; tcgen05.mma.cta_group::2.kind::f16 [%0], %1, %2, %3, p; }"
               ::"r"(t), "l"(a), "l"(b), "r"(idesc), "r"(acc));
}
__device__ __forceinline__ void tma_e(uint32_t dst, const CUtensorMap* m, uint32_t bar, int x, int y) {
  asm volatile("cp.async.bulk.tensor.2d.cta_group::2.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1, {%3, %4}], [%2];"
               ::"r"(dst), "l"((uint64_t)m), "r"(bar), "r"(x), "r"(y) : "memory");
}
__device__ __forceinline__ uint64_t sw128_desc(uint32_t addr) {
  return (uint64_t)((addr & 0x3FFFF) >> 4) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | ((uint64_t)1 << 46) |
         ((uint64_t)2 << 61);
}
__device__ __forceinline__ void cluster_sync() {
  asm volatile("barrier.cluster.arrive.release.aligned;\nbarrier.cluster.wait.acquire.aligned;" ::: "memory");
}
__device__ __forceinline__ float4 ldg_w(const float* g, uint64_t pol) {
  float4 v;
  asm volatile("ld.global.nc.L1::no_allocate.L2::cache_hint.v4.f32 {%0, %1, %2, %3}, [%4], %5;"
               : "=f"(v.x), "=f"(v.y), "=f"(v.z), "=f"(v.w) : "l"(g), "l"(pol));
  return v;
}
// k-block kb of this thread's eight W rows (rb + 2 i), floats 4 (lane & 15) .. +3 of the k-block.
__device__ __forceinline__ void load_kb(float4 (&b)[8], const float* src, int kb, uint64_t pol) {
#pragma unroll
  for (int i = 0; i < 8; ++i) b[i] = ldg_w(src + (size_t)(2 * i) * kD + kb * kBK, pol);
}
__device__ __forceinline__ uint32_t pack_h2(float lo, float hi) {   // round to nearest; lo in the low half
  uint32_t r;
  asm("cvt.rn.f16x2.f32 %0, %1, %2;" : "=r"(r) : "f"(hi), "f"(lo));
