}
__device__ __forceinline__ void arrive_cluster(uint32_t bar) {
  asm volatile("mbarrier.arrive.release.cluster.shared::cluster.b64 _, [%0];" ::"r"(bar) : "memory");
}
#endif

// Fallback pre-pass (used only when the fused path's co-residency check fails): emb [B, 3072] fp32 -> fp16.
__global__ void __launch_bounds__(256) emb_f16_kernel(const float* __restrict__ e, uint4* __restrict__ o, int n8) {
#if defined(__CUDA_ARCH_FEAT_SM100_ALL)
