    const float4 a = reinterpret_cast<const float4*>(e)[2 * i], b = reinterpret_cast<const float4*>(e)[2 * i + 1];
    o[i] = make_uint4(pack_h2(a.x, a.y), pack_h2(a.z, a.w), pack_h2(b.x, b.y), pack_h2(b.z, b.w));
