    }
  } else if (warp >= kCvtWarp0) {   // W converters: global fp32 -> registers -> fp16 SW128 stage, G rotating groups
    const int cw = warp - kCvtWarp0, g = cw / kGroupWarps, w = cw % kGroupWarps;
