  else if (warp >= kCvtWarp0) epilogue(p.nb - 1, (warp - kCvtWarp0) >> 2, kCvtWarps / 4);
  asm volatile("tcgen05.fence::before_thread_sync;");
  cluster_sync();
  if (warp == 3) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(p.tmem_cols));
  }
#endif
}
}  // namespace

// One launch on the caller's stream (two only if the fused path cannot be used: fp16 emb pre-pass, then the GEMM).
extern "C" int adamod_tc_h(const float* emb, const float* W, const float* bias, float* const* outs, void* emb16, int B,
                           cudaStream_t stream) {
  if (B < 1 || B > 1024 || emb16 == nullptr) return 430;
  TileCfg p;
  p.B = B;
  p.nb = B <= 512 ? 1 : 2;
  p.ntile = ((B + p.nb - 1) / p.nb + 15) / 16 * 16;
  p.n1 = p.ntile < 256 ? p.ntile : 256;
  p.n2 = p.ntile - p.n1;
  p.tmem_cols = p.n2 ? 512 : p.n1 <= 32 ? 32 : p.n1 <= 64 ? 64 : p.n1 <= 128 ? 128 : 256;
  p.n8 = B * kD / 8;
  const int stageBytes = kABlk + p.ntile / 2 * 128;
  const int maxStages = (p.nb == 2 && p.ntile >= 464) ? 4 : 3;   // r10: 4 stages only where measured faster
  p.stages = (kSmemDyn - 1024) / stageBytes;
  if (p.stages > maxStages) p.stages = maxStages;
  if (p.stages < kGroups) return 433;
  const int grid = 2 * kPairs;
  CUtensorMap mE1, mE2;
  cuuint32_t es[2] = {1, 1};
  // fp16 emb rows >= B are out of bounds and zero-filled by TMA.
  cuuint64_t dE[2] = {(cuuint64_t)kD, (cuuint64_t)B}, sE[1] = {(cuuint64_t)kD * 2};
  cuuint32_t bE1[2] = {kBK, (cuuint32_t)(p.n1 / 2)}, bE2[2] = {kBK, (cuuint32_t)(p.n2 ? p.n2 / 2 : 8)};
  if (cuTensorMapEncodeTiled(&mE1, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE1, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
                             CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
                             CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS)
    return 431;
  if (cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
                             CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
                             CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS)
    return 432;
  cudaLaunchAttribute at[1];
  at[0].id = cudaLaunchAttributeClusterDimension;
  at[0].val.clusterDim.x = 2;
  at[0].val.clusterDim.y = 1;
  at[0].val.clusterDim.z = 1;
  // One-time setup: smem attribute; the fused emb conversion makes CTAs wait on each other, so it is used only if all
  // 72 clusters fit at once (largest smem config); its two-word counter is zeroed once and reset by every call.
  static bool init = false;
  static unsigned* sync = nullptr;
  if (!init) {
    cudaFuncSetAttribute(tc_h_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn);
    cudaLaunchConfig_t oc = {};
    oc.gridDim = dim3(grid);
    oc.blockDim = dim3(kThreads);
    oc.dynamicSmemBytes = kSmemDyn;
    oc.attrs = at;
    oc.numAttrs = 1;
    int clusters = 0;
    if (cudaOccupancyMaxActiveClusters(&clusters, tc_h_kernel, &oc) != cudaSuccess) clusters = 0;
    if (clusters >= kPairs && cudaMalloc(&sync, 2 * sizeof(unsigned)) == cudaSuccess) {
      if (cudaMemset(sync, 0, 2 * sizeof(unsigned)) != cudaSuccess || cudaDeviceSynchronize() != cudaSuccess) sync = nullptr;
    } else {
      sync = nullptr;
    }
    cudaGetLastError();
    init = true;
  }
  p.fuse = sync != nullptr && (p.n8 + grid - 1) / grid * 32 <= p.stages * stageBytes;
  if (!p.fuse) emb_f16_kernel<<<(p.n8 + 255) / 256, 256, 0, stream>>>(emb, (uint4*)emb16, p.n8);
  OutPtrs op;
  for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(grid);
  cfg.blockDim = dim3(kThreads);
  cfg.dynamicSmemBytes = p.stages * stageBytes + 1024;
  cfg.stream = stream;
  cfg.attrs = at;
  cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, tc_h_kernel, W, mE1, mE2, bias, op, emb, (uint4*)emb16, sync, p);
  return (int)cudaGetLastError();
}
